    "shortDescription": "වනජීවීන්, සංස්කෘතික සංචාර, කඳුකර දසුන් සහ වෙරළේ කාලය එක් කරමින්, දින 19ක් සහ රාත්‍රී 18ක් පුරා ඔබේ පවුල සමඟ ශ්‍රී ලංකාව ගවේෂණය කරන්න.",
    "overview": "මීගමුවේ සිට කල්පිටිය, හබරණ, මහනුවර, නුවරඑළිය සහ ඇල්ල හරහා ගමන් කරන්න. ඉන්පසු කොළඹට සහ පිටත්ව යාමට පෙර යාල, වැලිගම සහ බෙන්තොට වෙත යන්න. මෙම ගමන් මාර්ගය සෆාරි, උරුම නැවතුම්, එළිමහන් ක්‍රියාකාරකම් සහ වෙරළබඩ විවේකය එක් කරයි.",
