    "overview": "බැලූන් අත්දැකීමක් සහ අනුරාධපුර සංචාරයක් සමඟ හබරණ, සීගිරිය, හිරිවඩුන්න සහ මින්නේරිය ගවේෂණය කරන්න. දඹුල්ල ගුහා විහාරය, මහනුවර දළදා මාළිගාව, සංස්කෘතික ප්‍රසංගයක්, අඹුළුවාව කුළුණ සහ රාජකීය උද්භිද උද්‍යානය සොයා යන්න. රම්බොඩ ඇල්ල, ග්‍රෙගරි වැව සහ ස්ට්‍රෝබෙරි ගොවිපොළක් සඳහා නුවරඑළිය හරහා ද, ආරුක්කු නවයේ පාලම, පුංචි ශ්‍රී පාදය සහ රාවණා ඇල්ල සඳහා ඇල්ල වෙත ද ගමන් කරන්න. දකුණු කොටසට යාල ජාතික වනෝද්‍යානය, මිරිස්ස, ගාල්ල ලන්දේසි බලකොටුව, කොස්ගොඩ මුහුදු කැස්බෑ පැටවුන් බිහිකරන මධ්‍යස්ථානය සහ බෙන්තොට හිරු බැසීමේ බෝට්ටු ගමනක් ඇතුළත් වේ. කොළඹ නගරය නැරඹීම, සාප්පු සවාරි සහ වීදි ආහාර සමඟ චාරිකාව අවසන් කරන්න.",
