    "overview": "මින්නේරිය වනජීවී නැරඹීම හිරිවඩුන්න ගම්මානය, සීගිරිය, උණුසුම් වායු බැලූන් අත්දැකීමක් සහ දඹුල්ල ගුහා විහාරය සමඟ එක් කරන්න. මහනුවරදී දළදා මාළිගාව සහ අඹුළුවාව කුළුණ නරඹා සංස්කෘතික ප්‍රසංගයක් අත්විඳින්න. ඉන්පසු තේ කර්මාන්තශාලාවකට සහ ඇල්ලේ ආකර්ෂණීය ස්ථාන වන ආරුක්කු නවයේ පාලම, පුංචි ශ්‍රී පාදය සහ රාවණා ඇල්ල වෙත යන්න. කොළඹ නගරය නැරඹීමට සහ සාප්පු සවාරි සඳහා කාලය ගත කිරීමට පෙර ගාල්ල ලන්දේසි බලකොටුව නරඹන්න.",
